fn remove_file_if_exists_legacy_compatible(path: &Path, context: &str) -> anyhow::Result<bool> {
    if !path.exists() {
        return Ok(false);
    }
    if !path.is_file() {
        return Err(anyhow!(
            "{context} path is not a file and cannot be cleared: {}",
            path.display()
        ));
    }
    std::fs::remove_file(path)
        .map_err(|error| anyhow!("failed clearing {context} {}: {error}", path.display()))?;
    Ok(true)
}

fn clear_syncplay_cli_gui_qsettings_filesystem_legacy_compatible(
    root: &Path,
) -> anyhow::Result<bool> {
    let mut changed = false;
    let syncplay_dir = root.join("Syncplay");
    for store in legacy_gui_qsettings_store_names_legacy_compatible() {
        for extension in [".conf", ".ini"] {
            let candidate = syncplay_dir.join(format!("{store}{extension}"));
            changed |= remove_file_if_exists_legacy_compatible(&candidate, "legacy GUI QSettings")?;
        }
    }
    Ok(changed)
}

fn clear_windows_registry_key_tree_legacy_compatible(key: &str) -> anyhow::Result<bool> {
    let query_status = Command::new("reg")
        .args(["query", key])
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .map_err(|error| anyhow!("failed querying registry key {key}: {error}"))?;
    if !query_status.success() {
        return Ok(false);
    }

    let output = Command::new("reg")
        .args(["delete", key, "/f"])
        .output()
        .map_err(|error| anyhow!("failed deleting registry key {key}: {error}"))?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        let stderr = stderr.trim();
        if stderr.is_empty() {
            return Err(anyhow!("failed deleting registry key {key}"));
        }
        return Err(anyhow!("failed deleting registry key {key}: {stderr}"));
    }
    Ok(true)
}

fn clear_syncplay_cli_gui_qsettings_windows_registry_legacy_compatible() -> anyhow::Result<bool> {
    let mut changed = false;
    for store in legacy_gui_qsettings_store_names_legacy_compatible() {
        let key = format!(r"HKEY_CURRENT_USER\Software\Syncplay\{store}");
        changed |= clear_windows_registry_key_tree_legacy_compatible(&key)?;
    }
    Ok(changed)
}

fn clear_syncplay_cli_gui_qsettings_macos_plists_legacy_compatible(
    preferences_dir: &Path,
) -> anyhow::Result<bool> {
    let mut changed = false;
    for store in legacy_gui_qsettings_store_names_legacy_compatible() {
        for candidate_name in [
            format!("com.Syncplay.{store}.plist"),
            format!("org.Syncplay.{store}.plist"),
            format!("Syncplay.{store}.plist"),
        ] {
            let candidate = preferences_dir.join(candidate_name);
            changed |= remove_file_if_exists_legacy_compatible(&candidate, "legacy GUI QSettings")?;
        }
    }
    Ok(changed)
}

fn clear_syncplay_cli_gui_qsettings_legacy_compatible() -> anyhow::Result<bool> {
    if let Some(root) = syncplay_cli_legacy_gui_qsettings_root_override() {
        return clear_syncplay_cli_gui_qsettings_filesystem_legacy_compatible(&root);
    }

    if cfg!(windows) {
        let mut changed = clear_syncplay_cli_gui_qsettings_windows_registry_legacy_compatible()?;
        if let Some(root) = default_syncplay_cli_config_root_legacy_compatible() {
            changed |= clear_syncplay_cli_gui_qsettings_filesystem_legacy_compatible(&root)?;
        }
        return Ok(changed);
    }

    if cfg!(target_os = "macos") {
        let mut changed = false;
        if let Some(home) = env_trimmed("HOME") {
            let preferences_dir = PathBuf::from(home).join("Library").join("Preferences");
            changed |=
                clear_syncplay_cli_gui_qsettings_macos_plists_legacy_compatible(&preferences_dir)?;
        }
        if let Some(root) = default_syncplay_cli_config_root_legacy_compatible() {
            changed |= clear_syncplay_cli_gui_qsettings_filesystem_legacy_compatible(&root)?;
        }
        return Ok(changed);
    }

    let Some(root) = default_syncplay_cli_config_root_legacy_compatible() else {
        return Ok(false);
    };
    clear_syncplay_cli_gui_qsettings_filesystem_legacy_compatible(&root)
}

fn protocol_lines_for_startup_playlist_load_from_file_legacy_compatible(
    path: &Path,
) -> anyhow::Result<Vec<String>> {
    if !path.is_file() {
        eprintln!(
            "warning: legacy --load-playlist-from-file skipped because file was not found: {}",
            path.display()
        );
        return Ok(Vec::new());
    }
    let contents = std::fs::read_to_string(path)
        .map_err(|error| anyhow!("failed reading playlist file {}: {error}", path.display()))?;
    let files = contents.lines().map(ToOwned::to_owned).collect::<Vec<_>>();
    if files.is_empty() {
        return Ok(Vec::new());
    }

    let playlist_change_message = ProtocolMessage::set(
        SetPayload::new().with_playlist_change(PlaylistChangePayload::new(files)),
    );
    let playlist_index_message =
        ProtocolMessage::set(SetPayload::new().with_playlist_index(PlaylistIndexPayload::new(0)));
    Ok(vec![
        encode_message_line(&playlist_change_message)?,
        encode_message_line(&playlist_index_message)?,
    ])
}

async fn emit_startup_playlist_load_from_file_legacy_compatible(
    writer: &mut tokio::net::tcp::OwnedWriteHalf,
    playlist_path: &str,
) -> anyhow::Result<bool> {
    let lines = protocol_lines_for_startup_playlist_load_from_file_legacy_compatible(Path::new(
        playlist_path,
    ))?;
    if lines.is_empty() {
        return Ok(false);
    }
    for line in &lines {
        write_protocol_line(writer, line).await?;
    }
    Ok(true)
}

fn parse_host_and_optional_port_from_host_arg_legacy_compatible(
    host_value: &str,
) -> (String, Option<u16>) {
    if host_value.matches(':').count() == 1 {
        let mut pieces = host_value.rsplitn(2, ':');
        let maybe_port = pieces.next().unwrap_or_default();
        let maybe_host = pieces.next().unwrap_or_default();
        if let Ok(port) = maybe_port.parse::<u16>() {
            return (maybe_host.to_owned(), Some(port));
        }
        return (maybe_host.to_owned(), None);
    }

    if host_value.starts_with('[') {
        if let Some(end_bracket) = host_value.find(']') {
            let host = &host_value[..=end_bracket];
            if let Some(port_text) = host_value
                .get(end_bracket + 1..)
                .and_then(|s| s.strip_prefix(':'))
            {
                if let Ok(port) = port_text.parse::<u16>() {
                    return (host.to_owned(), Some(port));
                }
            }
            return (host.to_owned(), None);
        }
    }

    if host_value.matches(':').count() > 1 {
        return (format!("[{host_value}]"), None);
    }

    (host_value.to_owned(), None)
}

fn take_next_non_flag_arg_legacy_compatible<I>(args: &mut std::iter::Peekable<I>) -> Option<String>
where
    I: Iterator<Item = String>,
{
    if args.peek().is_some_and(|value| !value.starts_with('-')) {
        return args.next();
    }
    None
}

fn parse_legacy_client_arg_overrides<I, S>(args: I) -> LegacyClientArgOverrides
where
    I: IntoIterator<Item = S>,
    S: AsRef<str>,
{
    let mut overrides = LegacyClientArgOverrides::default();
    let mut iter = args
        .into_iter()
        .map(|value| value.as_ref().to_owned())
        .peekable();

    while let Some(arg) = iter.next() {
        if arg == "--" {
            let mut trailing_args = iter.collect::<Vec<_>>();
            if !trailing_args.is_empty() {
                overrides.connect_requested = true;
                if overrides.file.is_none() {
                    let first = trailing_args.remove(0);
                    if first.starts_with("--") {
                        // Python ConfigurationGetter (argparse) fills positional `file` first after `--`,
                        // then rewrites `file="--foo"` into the player-args list.
                        overrides.player_args.push(first);
                    } else {
                        overrides.file = Some(first);
                    }
                }
                overrides.player_args.extend(trailing_args);
            }
            break;
        }
        match arg.as_str() {
            "-h" | "--help" => {
                overrides.show_help = true;
            }
            "-v" | "--version" => {
                overrides.show_version = true;
            }
            "-d" | "--debug" => {
                overrides.debug_requested = true;
            }
            "-g" | "--force-gui-prompt" => {
                overrides.force_gui_prompt_requested = true;
            }
            "--clear-gui-data" => {
                overrides.clear_gui_data_requested = true;
            }
            "--no-store" => {
                overrides.no_store = true;
            }
            "-psn" => {
                let _ = iter.next();
            }
            "--language" => {
                overrides.language = take_next_non_flag_arg_legacy_compatible(&mut iter);
            }
            "--player-path" => {
                overrides.connect_requested = true;
                overrides.player_path = take_next_non_flag_arg_legacy_compatible(&mut iter);
            }
            "--load-playlist-from-file" => {
                overrides.load_playlist_from_file =
                    take_next_non_flag_arg_legacy_compatible(&mut iter);
            }
            "--no-gui" => {
                overrides.connect_requested = true;
            }
            "-a" | "--host" => {
                overrides.connect_requested = true;
                if let Some(value) = take_next_non_flag_arg_legacy_compatible(&mut iter) {
                    let (host, port) =
                        parse_host_and_optional_port_from_host_arg_legacy_compatible(&value);
                    if !host.is_empty() {
                        overrides.host = Some(host);
                    }
                    if port.is_some() {
                        overrides.port = port;
                    }
                }
            }
            "-n" | "--name" => {
                overrides.connect_requested = true;
                overrides.username = take_next_non_flag_arg_legacy_compatible(&mut iter);
            }
            "-r" | "--room" => {
                overrides.connect_requested = true;
                overrides.room = take_next_non_flag_arg_legacy_compatible(&mut iter);
            }
            "-p" | "--password" => {
                overrides.connect_requested = true;
                overrides.controlled_room_password_override =
                    take_next_non_flag_arg_legacy_compatible(&mut iter);
            }
            _ => {
                if arg.starts_with('-') {
                    overrides.unknown_options.push(arg);
                } else if overrides.file.is_none() {
                    overrides.connect_requested = true;
                    overrides.file = Some(arg);
                } else {
                    overrides.connect_requested = true;
                    overrides.player_args.push(arg);
                }
            }
        }
    }

    overrides
}

