            writer
                .write_all(
                    b"{\"Hello\":{\"username\":\"cli-user\",\"room\":{\"name\":\"cli-room\"},\"version\":\"1.7.5\",\"features\":{\"readiness\":true}}}\n",
                )
                .await
                .expect("server hello write should succeed");

